input.command:
python3 - <<'EOF' > /private/tmp/claude-501/-Users-akima-workspace-claude-plugins/feec6288-dfe0-4c5b-8d07-0e5eda3b96f8/scratchpad/code-hits.txt
import tomllib,re,subprocess,collections
t=tomllib.load(open('.claude/akm-claude-plugins/wording-guard/terms.toml','rb'))
pats=[]
for x in t['terms']:
    if x.get('verdict')!='avoid': continue
    p=x['pattern']
    if p.startswith('/') and p.endswith('/'): r=re.compile(p[1:-1])
    else: r=re.compile(re.escape(p))
    pats.append((p,r))
files=[f for f in subprocess.check_output(['git','ls-files'],text=True).split('\n') if f and not f.endswith('.md')]
frozen=('docs/plans/','docs/review-triage/','docs/solutions/','tmp/')
hits=collections.defaultdict(list)
for f in files:
    if f.startswith(frozen): continue
    try: lines=open(f,encoding='utf-8').read().split('\n')
    except Exception: continue
    for i,l in enumerate(lines,1):
        for p,r in pats:
            m=r.search(l)
            if m: hits[f].append((i,m.group(0),l.strip()[:120]))
tot=0
for f in sorted(hits):
    for i,w,l in hits[f]:
        tot+=1; print(f"{f}:{i}\t{w}\t{l}")
print("TOTAL",tot,"FILES",len(hits))
EOF
